const driveFile = $input.first().json;
const podcastUrl = driveFile.webViewLink || driveFile.webContentLink;
const today = new Date().toLocaleDateString("de-DE", { weekday: "long", year: "numeric", month: "long", day: "numeric" });

return [{
  json: {
    podcastUrl: podcastUrl,
    date: today,
    message: `🎙️ Dein täglicher AI News Podcast ist fertig!\n\nDatum: ${today}\nDauer: 19 Minuten\n\nJetzt anhören: ${podcastUrl}`,
    emailSubject: `AI News Podcast - ${today}`,
    emailBody: `<h2>🎙️ Dein täglicher AI News Podcast</h2><p>Hallo!</p><p>Dein personalisierter AI News Podcast für <strong>${today}</strong> ist fertig.</p><p><strong>Dauer:</strong> 19 Minuten</p><p><a href="${podcastUrl}" style="background-color: #4CAF50; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px;">Podcast anhören</a></p><p>Bleib informiert über die neuesten AI-Entwicklungen!</p>`
  },
  binary: $input.first().binary
}];

// Get the search query from the AI agent - be flexible about the format
const input = $input.first().json;

// Try different possible field names
const query = input.q || input.query || input.search || input.search_query || input.searchQuery;

if (!query) {
  console.log('Input received:', JSON.stringify(input, null, 2));
  throw new Error('No search query provided. Expected parameter: q, query, or search. Received: ' + JSON.stringify(input));
}

console.log('Searching for:', query);

// Make request to SerpAPI
const response = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://serpapi.com/search',
  qs: {
    engine: 'google',
    q: query,
    api_key: 'YOUR_SERPAPI_KEY',
    tbs: 'qdr:d'  // Filter: last 24 hours
  },
  json: true
});

// Extract and format the results
const results = response.organic_results || [];
const formattedResults = results.slice(0, 10).map(r => ({
  title: r.title,
  snippet: r.snippet,
  link: r.link,
  date: r.date || 'unknown'
}));

console.log('Found', formattedResults.length, 'results');

return [{ json: { results: formattedResults, query: query } }];

// ========================================
// COMPREHENSIVE AI NEWS RESEARCH - IMPROVED
// Sources: YouTube, RSS (10+ feeds), ArXiv, Google News, Hacker News, Web Scraping
// With URL-based deduplication and freshness filtering
// ========================================

let allNews = [];
const seenUrls = new Set();   // URL-basierte Deduplizierung
const seenTitles = new Set(); // Titel-basierte Deduplizierung

const today = new Date();
const yesterday = new Date(today);
yesterday.setDate(yesterday.getDate() - 1);
const dateQuery = yesterday.toISOString().split('T')[0]; // Format: YYYY-MM-DD
const twoDaysAgo = new Date(today);
twoDaysAgo.setDate(twoDaysAgo.getDate() - 2);

console.log('=== STARTING COMPREHENSIVE AI NEWS RESEARCH (IMPROVED) ===');
console.log(`Target date: ${dateQuery}`);

// Helper: Dedupliziert hinzufügen
function addNews(item) {
  if (!item.title || item.title.length < 10) return;

  const normalizedTitle = item.title.toLowerCase().replace(/[^a-z0-9äöüß]/g, '').substring(0, 60);
  const normalizedUrl = (item.url || '').replace(/[?#].*$/, '').toLowerCase();

  if (seenTitles.has(normalizedTitle)) return;
  if (normalizedUrl && seenUrls.has(normalizedUrl)) return;

  seenTitles.add(normalizedTitle);
  if (normalizedUrl) seenUrls.add(normalizedUrl);
  allNews.push(item);
}

// ========================================
// 1. GOOGLE NEWS RSS - Sehr aktuell, strukturiert
// ========================================
console.log('\n[1/6] Fetching Google News RSS...');
const googleNewsFeeds = [
  'https://news.google.com/rss/search?q=artificial+intelligence+AI&hl=de&gl=DE&ceid=DE:de&tbs=qdr:d',
  'https://news.google.com/rss/search?q=ChatGPT+OpenAI+Anthropic+Claude&hl=de&gl=DE&ceid=DE:de&tbs=qdr:d',
  'https://news.google.com/rss/search?q=LLM+Sprachmodell+KI+2025&hl=de&gl=DE&ceid=DE:de&tbs=qdr:d'
];

for (const feedUrl of googleNewsFeeds) {
  try {
    const rssResponse = await this.helpers.httpRequest({
      method: 'GET',
      url: feedUrl,
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; NewsBot/1.0)' },
      timeout: 8000
    });

    const itemRegex = /<item>(.*?)<\/item>/gs;
    const items = [...rssResponse.matchAll(itemRegex)];

    items.slice(0, 3).forEach(itemMatch => {
      const item = itemMatch[1];
      const titleMatch = /<title>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/s.exec(item);
      const linkMatch = /<link>(.*?)<\/link>/.exec(item) || /<link\s*\/?>\s*(.*?)<\/link>/.exec(item);
      const descMatch = /<description>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/description>/s.exec(item);
      const pubDateMatch = /<pubDate>(.*?)<\/pubDate>/.exec(item);

      if (titleMatch) {
        const pubDate = pubDateMatch ? new Date(pubDateMatch[1]) : new Date();
        if (pubDate >= twoDaysAgo) {
          addNews({
            title: titleMatch[1].replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/<[^>]*>/g, '').trim(),
            description: descMatch ? descMatch[1].replace(/<[^>]*>/g, '').substring(0, 300) : '',
            url: (linkMatch ? linkMatch[1] : '').trim(),
            source: 'Google News',
            type: 'article',
            date: pubDateMatch ? pubDateMatch[1] : dateQuery
          });
        }
      }
    });

    console.log(`✓ Google News RSS fetched`);
  } catch (error) {
    console.log(`✗ Google News error: ${error.message}`);
  }
}

// ========================================
// 2. KURATIERTE RSS FEEDS - Hochwertige Quellen
// ========================================
console.log('\n[2/6] Fetching curated RSS feeds...');
const rssFeeds = [
  { url: 'https://www.artificialintelligence-news.com/feed/', name: 'AI News' },
  { url: 'https://venturebeat.com/category/ai/feed/', name: 'VentureBeat AI' },
  { url: 'https://www.heise.de/thema/K%C3%BCnstliche-Intelligenz?view=rss', name: 'Heise KI' },
  { url: 'https://techcrunch.com/category/artificial-intelligence/feed/', name: 'TechCrunch AI' },
  { url: 'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml', name: 'The Verge AI' },
  { url: 'https://feeds.feedburner.com/blogspot/gJZg', name: 'Google AI Blog' },
  { url: 'https://www.technologyreview.com/feed/', name: 'MIT Tech Review' }
];

for (const feed of rssFeeds) {
  try {
    const rssResponse = await this.helpers.httpRequest({
      method: 'GET',
      url: feed.url,
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
      timeout: 8000
    });

    const itemRegex = /<item>(.*?)<\/item>/gs;
    const items = [...rssResponse.matchAll(itemRegex)];

    items.slice(0, 2).forEach(itemMatch => {
      const item = itemMatch[1];
      const titleMatch = /<title>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/s.exec(item);
      const linkMatch = /<link>(.*?)<\/link>/.exec(item);
      const descMatch = /<description>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/description>/s.exec(item);
      const pubDateMatch = /<pubDate>(.*?)<\/pubDate>/.exec(item);

      if (titleMatch && linkMatch) {
        const pubDate = pubDateMatch ? new Date(pubDateMatch[1]) : new Date();
        const desc = descMatch ? descMatch[1].replace(/<[^>]*>/g, '').substring(0, 280) : 'Keine Beschreibung verfügbar';
        addNews({
          title: titleMatch[1].replace(/&amp;/g, '&').replace(/&#8217;/g, "'").replace(/<[^>]*>/g, '').trim(),
          description: desc,
          url: linkMatch[1].trim(),
          source: feed.name,
          type: 'article',
          date: pubDateMatch ? pubDateMatch[1] : dateQuery
        });
      }
    });

    console.log(`✓ RSS: ${feed.name}`);
  } catch (error) {
    console.log(`✗ RSS error (${feed.name}): ${error.message}`);
  }
}

// ========================================
// 3. ARXIV - KI Research Papers
// ========================================
console.log('\n[3/6] Fetching ArXiv AI papers...');
try {
  const arxivResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://rss.arxiv.org/rss/cs.AI',
    headers: { 'User-Agent': 'Mozilla/5.0 (compatible; ResearchBot/1.0)' },
    timeout: 8000
  });

  const itemRegex = /<item>(.*?)<\/item>/gs;
  const items = [...arxivResponse.matchAll(itemRegex)];

  items.slice(0, 3).forEach(itemMatch => {
    const item = itemMatch[1];
    const titleMatch = /<title>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/s.exec(item);
    const linkMatch = /<link>(.*?)<\/link>/.exec(item);
    const descMatch = /<description>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/description>/s.exec(item);

    if (titleMatch && linkMatch) {
      addNews({
        title: titleMatch[1].replace(/<[^>]*>/g, '').trim(),
        description: (descMatch ? descMatch[1].replace(/<[^>]*>/g, '') : '').substring(0, 300),
        url: linkMatch[1].trim(),
        source: 'ArXiv (cs.AI)',
        type: 'research',
        date: dateQuery
      });
    }
  });

  console.log('✓ ArXiv papers fetched');
} catch (error) {
  console.log(`✗ ArXiv error: ${error.message}`);
}

// ========================================
// 4. HACKER NEWS - Community Top Stories
// ========================================
console.log('\n[4/6] Fetching Hacker News AI stories...');
try {
  const hnResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://hnrss.org/newest?q=AI+OR+LLM+OR+Claude+OR+GPT+OR+Gemini&points=50',
    headers: { 'User-Agent': 'Mozilla/5.0 (compatible; NewsBot/1.0)' },
    timeout: 8000
  });

  const itemRegex = /<item>(.*?)<\/item>/gs;
  const items = [...hnResponse.matchAll(itemRegex)];

  items.slice(0, 3).forEach(itemMatch => {
    const item = itemMatch[1];
    const titleMatch = /<title>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/s.exec(item);
    const linkMatch = /<link>(.*?)<\/link>/.exec(item);
    const descMatch = /<description>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/description>/s.exec(item);

    if (titleMatch && linkMatch) {
      addNews({
        title: titleMatch[1].replace(/<[^>]*>/g, '').trim(),
        description: (descMatch ? descMatch[1].replace(/<[^>]*>/g, '') : '').substring(0, 250),
        url: linkMatch[1].trim(),
        source: 'Hacker News',
        type: 'community',
        date: dateQuery
      });
    }
  });

  console.log('✓ Hacker News stories fetched');
} catch (error) {
  console.log(`✗ Hacker News error: ${error.message}`);
}

// ========================================
// 5. YOUTUBE - AI News Videos
// ========================================
console.log('\n[5/6] Searching YouTube...');
try {
  const youtubeQuery = 'AI artificial intelligence news today';
  const ytResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://www.youtube.com/results',
    qs: {
      search_query: youtubeQuery,
      sp: 'CAISAhAB'
    },
    headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
    timeout: 10000
  });

  const videoRegex = /"videoId":"([^"]+)".*?"title":\{"runs":\[\{"text":"([^"]+)"\}\]/g;
  const videos = [...ytResponse.matchAll(videoRegex)];

  videos.slice(0, 2).forEach(match => {
    addNews({
      title: match[2].replace(/\\u[\dA-F]{4}/gi, '').trim(),
      description: 'YouTube Video über aktuelle KI-Entwicklungen',
      url: `https://www.youtube.com/watch?v=${match[1]}`,
      source: 'YouTube',
      type: 'video',
      date: dateQuery
    });
  });

  console.log('✓ YouTube videos found');
} catch (error) {
  console.log(`✗ YouTube error: ${error.message}`);
}

// ========================================
// 6. DUCKDUCKGO WEB SEARCH - Fallback
// ========================================
console.log('\n[6/6] DuckDuckGo web search fallback...');
try {
  const searchQuery = `KI Künstliche Intelligenz Neuigkeiten ${dateQuery}`;
  const searchResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://html.duckduckgo.com/html/',
    qs: { q: searchQuery },
    headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
    timeout: 8000
  });

  const resultRegex = /<a[^>]*class="result__a"[^>]*href="([^"]+)"[^>]*>([^<]+)<\/a>.*?<a[^>]*class="result__snippet"[^>]*>([^<]+)<\/a>/gs;
  const results = [...searchResponse.matchAll(resultRegex)];

  results.slice(0, 3).forEach(match => {
    addNews({
      title: match[2].trim(),
      description: match[3].trim().substring(0, 250),
      url: match[1],
      source: 'DuckDuckGo',
      type: 'search',
      date: dateQuery
    });
  });

  console.log('✓ DuckDuckGo search done');
} catch (error) {
  console.log(`✗ DuckDuckGo error: ${error.message}`);
}

// ========================================
// FINAL: Format and Return
// ========================================
console.log('\n=== RESEARCH COMPLETE ===');
console.log(`Total unique news items: ${allNews.length}`);

// Fallback content wenn keine News gefunden
let newsText = '';

if (allNews.length === 0) {
  newsText = `Heute konnten trotz umfassender Recherche keine aktuellen KI-Nachrichten abgerufen werden.\n\n`;
  newsText += `Relevante Dauerthemen für den Podcast:\n`;
  newsText += `1. Stand der LLM-Entwicklung 2025 (GPT-4o, Claude 3.5, Gemini 1.5)\n`;
  newsText += `2. Open-Source vs. Closed-Source Modelle: Aktuelle Abwägungen\n`;
  newsText += `3. RAG-Architekturen und Vektorsuche in der Praxis\n`;
  newsText += `4. AI-Kosten-Optimierung: Batching, Caching, kleinere Modelle\n`;
  newsText += `5. EU AI Act: Was müssen Entwickler jetzt wissen?`;
} else {
  allNews.forEach((item, i) => {
    newsText += `**News ${i + 1}: ${item.title}**\n`;
    if (item.date) newsText += `Datum: ${item.date}\n`;
    newsText += `${item.description}\n`;
    newsText += `Quelle: ${item.source} (${item.type}) - ${item.url}\n\n`;
  });
}

// Quellenübersicht
const sourceBreakdown = {};
allNews.forEach(n => {
  sourceBreakdown[n.source] = (sourceBreakdown[n.source] || 0) + 1;
});

const dateStr = today.toLocaleDateString('de-DE', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

return [{
  json: {
    news: newsText,
    date: dateStr,
    totalArticles: allNews.length,
    sourceBreakdown: sourceBreakdown
  }
}];
